    "journeys": {
      "journeys/an-invitation-is-used-once.ts": {
        "name": "an invitation is used once",
        "file": "journeys/an-invitation-is-used-once.ts",
        "cast": {
          "ada": {
            "kind": "role",
            "role": "organization.owner"
          },
          "olga": {
            "kind": "signed-in"
          }
        },
        "starts": "invited",
        "steps": [
          {
            "title": "olga accepts the invitation ada sent her",
            "call": {
              "actor": "olga",
              "operation": "invitation.accept",
              "payload": {
                "invitation": {
                  "ref": [
                    "world",
                    "invitation"
                  ]
                }
              }
            },
            "checks": [
              {
                "kind": "expect-equal",
                "value": {
                  "ref": [
                    "world",
                    "organization"
                  ]
                }
              },
              {
                "kind": "expect",
                "match": "^mem_[0-9a-z]+$",
                "flags": ""
              },
              {
                "kind": "emits",
                "event": "InvitationAccepted",
                "fields": {
                  "invitation": {
                    "ref": [
                      "world",
                      "invitation"
                    ]
                  },
                  "membership": {
                    "ref": [
                      "last",
                      "membership"
                    ]
                  }
                }
              },
              {
                "kind": "is-in",
                "thing": "invitation",
                "id": {
                  "ref": [
                    "world",
                    "invitation"
                  ]
                },
                "state": "accepted"
              },
              {
                "kind": "spans",
                "present": [
                  "invitation.accept",
                  "invitation.accept.join"
                ],
                "absent": []
              }
            ]
          },
          {
            "title": "accepting it again is refused",
            "call": {
              "actor": "olga",
              "operation": "invitation.accept",
              "payload": {
                "invitation": {
                  "ref": [
                    "world",
                    "invitation"
                  ]
                }
              }
            },
            "checks": [
              {
                "kind": "refuses",
                "error": "invitation.notFrom",
                "fields": {
                  "state": "accepted"
                }
              },
              {
                "kind": "no-events"
              },
              {
                "kind": "is-in",
                "thing": "invitation",
                "id": {
                  "ref": [
                    "world",
                    "invitation"
                  ]
                },
                "state": "accepted"
              },
              {
                "kind": "spans",
                "present": [],
                "absent": [
                  "invitation.accept.join"
                ]
              }
            ]
          },
          {
            "title": "ada can't revoke an invitation that has been accepted",
            "call": {
              "actor": "ada",
              "operation": "invitation.revoke",
              "payload": {
                "invitation": {
                  "ref": [
                    "world",
                    "invitation"
                  ]
                }
              }
            },
            "checks": [
