  "journeys": {
    "journeys/a-name-is-claimed-once.ts": {
      "name": "a name is claimed once",
      "file": "journeys/a-name-is-claimed-once.ts",
      "cast": {
        "aaron": {
          "kind": "signed-in"
        },
        "bob": {
          "kind": "signed-in"
        },
        "visitor": {
          "kind": "anyone"
        }
      },
      "starts": "claimed-aaron",
      "steps": [
        {
          "title": "retrying the first request returns the same handle and does no work",
          "call": {
            "actor": "aaron",
            "operation": "handle.claim",
            "payload": {
              "name": "aaron"
            },
            "request": "first-claim"
          },
          "checks": [
            {
              "kind": "expect-equal",
              "value": {
                "ref": [
                  "world",
                  "aaronHandle"
                ]
              }
            },
            {
              "kind": "no-events"
            },
            {
              "kind": "spans",
              "present": [],
              "absent": [
                "handle.claim.load",
                "handle.claim.record"
              ]
            }
          ]
        },
        {
          "title": "a fresh request to claim the same name is refused",
          "call": {
            "actor": "aaron",
            "operation": "handle.claim",
            "payload": {
              "name": "aaron"
            },
            "request": "another-claim"
          },
          "checks": [
            {
              "kind": "refuses",
              "error": "HandleTaken",
              "fields": {
                "code": "HN-001"
              }
            },
            {
              "kind": "no-events"
            },
            {
              "kind": "spans",
              "present": [],
              "absent": [
                "handle.claim.record"
              ]
            }
          ]
        },
        {
          "title": "another person cannot claim the name even with the same request key",
          "call": {
            "actor": "bob",
            "operation": "handle.claim",
            "payload": {
              "name": "aaron"
            },
            "request": "first-claim"
          },
          "checks": [
            {
              "kind": "refuses",
              "error": "HandleTaken",
              "fields": {
                "code": "HN-001"
              }
            },
            {
              "kind": "no-events"
            }
          ]
        },
        {
          "title": "aaron cannot claim another name while he owns this one",
          "call": {
            "actor": "aaron",
            "operation": "handle.claim",
            "payload": {
              "name": "second"
            }
          },
          "checks": [
            {
              "kind": "refuses",
              "error": "HandleAlreadyOwned",
              "fields": {}
            },
            {
              "kind": "no-events"
            }
          ]
        },
        {
          "title": "anyone can resolve the name to the original handle",
          "call": {
            "actor": "visitor",
            "operation": "handle.resolve",
            "payload": {
              "name": "aaron"
            }
          },
          "checks": [
            {
              "kind": "expect-equal",
              "value": {
                "ref": [
                  "world",
                  "aaronHandle"
                ]
              }
            },
            {
              "kind": "no-events"
            }
          ]
        },
        {
          "title": "a stranger cannot release the handle",
          "call": {
            "actor": "bob",
            "operation": "handle.release",
            "payload": {
              "handle": {
                "ref": [
                  "world",
                  "aaronHandle"
                ]
              }
            }
          },
          "checks": [
            {
              "kind": "refuses",
              "error": "NotAllowed",
              "fields": {}
            },
            {
              "kind": "no-events"
            },
            {
              "kind": "spans",
              "present": [],
              "absent": [
                "handle.release"
              ]
            }
          ]
        },
        {
          "title": "aaron puts a link on his page before releasing the name",
          "call": {
            "actor": "aaron",
            "operation": "link.add",
            "payload": {
              "title": "Original owner's site",
              "url": "https://example.org"
            }
          },
          "checks": [
            {
              "kind": "expect",
              "match": "^lnk_[0-9a-z]+$",
              "flags": ""
            }
          ]
        },
        {
          "title": "aaron releases his handle",
          "call": {
            "actor": "aaron",
            "operation": "handle.release",
            "payload": {
              "handle": {
                "ref": [
                  "world",
                  "aaronHandle"
                ]
              }
            }
          },
          "checks": [
            {
              "kind": "emits",
              "event": "HandleReleased",
              "fields": {
                "handle": {
                  "ref": [
                    "world",
                    "aaronHandle"
                  ]
                },
                "name": "aaron"
              }
            },
            {
              "kind": "is-in",
              "thing": "handle",
              "id": {
                "ref": [
                  "world",
                  "aaronHandle"
                ]
              },
              "state": "released"
            }
          ]
        },
        {
          "title": "the owner cannot release it twice",
          "call": {
            "actor": "aaron",
            "operation": "handle.release",
            "payload": {
              "handle": {
                "ref": [
                  "world",
                  "aaronHandle"
                ]
              }
            }
          },
          "checks": [
            {
              "kind": "refuses",
              "error": "handle.notFrom",
              "fields": {
                "state": "released"
              }
            },
            {
              "kind": "no-events"
            },
            {
              "kind": "spans",
              "present": [],
              "absent": [
                "handle.release.record"
              ]
            }
          ]
        },
        {
          "title": "the released name no longer resolves",
          "call": {
            "actor": "visitor",
            "operation": "handle.resolve",
            "payload": {
              "name": "aaron"
            }
          },
          "checks": [
            {
              "kind": "refuses",
              "error": "HandleNotFound",
              "fields": {}
            },
            {
              "kind": "no-events"
            }
          ]
        },
        {
          "title": "the released name has no public page",
          "call": {
            "actor": "visitor",
            "operation": "profile.get",
            "payload": {
              "handle": "aaron"
            }
          },
          "checks": [
            {
              "kind": "refuses",
              "error": "ProfileNotFound",
              "fields": {}
            },
            {
              "kind": "no-events"
            }
          ]
        },
        {
          "title": "another person can claim the released name",
          "call": {
            "actor": "bob",
            "operation": "handle.claim",
            "payload": {
              "name": "aaron"
            }
          },
          "checks": [
            {
              "kind": "emits",
              "event": "HandleClaimed",
              "fields": {
                "handle": {
                  "ref": [
                    "last",
                    "handle"
                  ]
                },
                "name": "aaron"
              }
            },
            {
              "kind": "is-in",
              "thing": "handle",
              "id": {
                "ref": [
                  "last",
                  "handle"
                ]
              },
              "state": "claimed"
            }
          ]
        },
        {
          "title": "the old owner cannot release the new owner's name",
          "call": {
            "actor": "aaron",
            "operation": "handle.release",
            "payload": {
              "handle": {
                "ref": [
                  "last",
                  "handle"
                ]
              }
            }
          },
          "checks": [
            {
              "kind": "refuses",
              "error": "NotAllowed",
              "fields": {}
            },
            {
              "kind": "no-events"
            }
          ]
        },
        {
          "title": "the new owner's public page contains none of the old owner's links",
          "call": {
            "actor": "visitor",
            "operation": "profile.get",
            "payload": {
              "handle": "aaron"
            }
          },
          "checks": [
            {
              "kind": "expect-equal",
              "value": {
                "handle": "aaron",
                "links": []
              }
            },
            {
              "kind": "no-events"
            }
          ]
        }
      ],
      "sourceHash": "b017632542999cdcfe8008e958c86dc29c099e1211f21134a8300e360f522873"
    },
